const metricInput = document.getElementById('metric-input');
const aggSelect = document.getElementById('agg-select');
const queryBtn = document.getElementById('query-btn');
const resultsContent = document.getElementById('results-content');

async function executeQuery() {
  const metric = metricInput.value.trim();
  if (!metric) return;

  queryBtn.disabled = true;
  queryBtn.textContent = 'Running...';
  resultsContent.innerHTML = '<p class="placeholder">Executing query...</p>';

  try {
    const r = await fetch('/api/query', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ metric, agg: aggSelect.value }),
    });
    const d = await r.json();

    if (d.status === 'error') {
      resultsContent.innerHTML = `<p class="error-msg">${d.message}</p>`;
    } else if (d.resultCount > 0) {
      let html = '';
      d.results.forEach((r, idx) => {
        const lbl = Object.entries(r.labels || {}).map(([k,v]) => `${k}="${v}"`).join(', ');
        html += `<div class="result-row"><span>#${idx+1}</span><span class="result-labels">${lbl}</span><span class="result-value">${r.value}</span></div>`;
      });
      resultsContent.innerHTML = html || '<p class="placeholder">No results.</p>';
    } else {
      resultsContent.innerHTML = '<p class="placeholder">No results.</p>';
    }
  } catch (e) {
    resultsContent.innerHTML = '<p class="error-msg">Request failed</p>';
  }

  queryBtn.disabled = false;
  queryBtn.textContent = 'Execute';
}

queryBtn.addEventListener('click', executeQuery);
